const PACK_NODES = {
  pipelines: 'Code in JavaScript',
  custom_fields: 'Code in JavaScript1',
  tags: 'Code in JavaScript2',
  salesbots: 'Code in JavaScript3',
  leads_sample: 'Code in JavaScript4',
  conversation_samples: 'Code in JavaScript5'
};

function readNodeItems(nodeName) {
  try {
    return $(nodeName).all().map(item => item.json);
  } catch {
    return [];
  }
}

function parseJsonMaybe(value) {
  if (typeof value !== 'string') return value;

  const trimmed = value.trim();
  if (!trimmed) return value;

  if (
    (trimmed.startsWith('{') && trimmed.endsWith('}')) ||
    (trimmed.startsWith('[') && trimmed.endsWith(']'))
  ) {
    try {
      return JSON.parse(trimmed);
    } catch {
      return value;
    }
  }

  return value;
}

function unwrap(value) {
  if (!value) return value;

  const parsed = parseJsonMaybe(value);

  if (parsed !== value) {
    return unwrap(parsed);
  }

  if (value.data != null) {
    const parsedData = parseJsonMaybe(value.data);
    if (parsedData && typeof parsedData === 'object') return unwrap(parsedData);
  }

  if (value.body != null) {
    const parsedBody = parseJsonMaybe(value.body);
    if (parsedBody && typeof parsedBody === 'object') return unwrap(parsedBody);
  }

  return value;
}

function arr(value) {
  if (value == null) return [];
  if (Array.isArray(value)) return value;
  const parsed = unwrap(value);
  if (Array.isArray(parsed)) return parsed;
  if (parsed && typeof parsed === 'object') return Object.values(parsed);
  return [];
}

function asArrayPreserveObjects(value) {
  if (value == null) return [];
  if (Array.isArray(value)) return value;
  const parsed = unwrap(value);
  if (Array.isArray(parsed)) return parsed;
  return [];
}

function looksLikeEntity(value, section) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;

  if (section === 'pipelines') {
    return value.id != null && (value._embedded?.statuses || value.statuses || value.name);
  }

  if (section === 'custom_fields') {
    return value.id != null && (value.type || value.name || value.code || value.entity_type === 'leads');
  }

  if (section === 'tags') {
    return value.id != null && value.name != null;
  }

  if (section === 'salesbots') {
    return value.id != null && (value.name || value.script || value.scenario || value.type || value.type_functionality);
  }

  if (section === 'leads_sample') {
    return value.id != null && (value.pipeline_id != null || value.status_id != null || value.name);
  }

  return false;
}

function embeddedList(page, keys, section) {
  const body = unwrap(page);
  const keyList = Array.isArray(keys) ? keys : [keys];

  if (!body) return [];

  if (Array.isArray(body)) {
    return body.flatMap(item => embeddedList(item, keyList, section));
  }

  for (const key of keyList) {
    if (body[key] != null) return arr(body[key]);
    if (body._embedded?.[key] != null) return arr(body._embedded[key]);
  }

  if (body.data != null) {
    const data = unwrap(body.data);
    if (Array.isArray(data)) return data;
    return embeddedList(data, keyList, section);
  }

  if (looksLikeEntity(body, section)) return [body];

  return [];
}

function collectFromPack(section, keys) {
  const packItems = readNodeItems(PACK_NODES[section]);

  const pages = packItems.flatMap(item => {
    if (item.pages != null) return arr(item.pages);
    return [item];
  });

  return pages.flatMap(page => embeddedList(page, keys, section));
}

function normalizeEnums(enums) {
  if (!enums) return [];

  return arr(enums).map(e => ({
    value: e?.value ?? e?.name ?? e,
    id: e?.id ?? e?.enum_id ?? null,
    sort: e?.sort ?? null,
    raw: e
  }));
}

function walk(value, visitor, path = []) {
  visitor(value, path);

  if (Array.isArray(value)) {
    value.forEach((item, index) => walk(item, visitor, path.concat(index)));
    return;
  }

  if (value && typeof value === 'object') {
    Object.entries(value).forEach(([key, child]) => walk(child, visitor, path.concat(key)));
  }
}

function pathText(path) {
  return path.map(String).join('.');
}

function unique(items) {
  const seen = new Set();

  return items.filter(item => {
    const key = JSON.stringify(item);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function scanIds(value, ids) {
  const found = {
    pipeline_ids: [],
    stage_ids: [],
    custom_field_ids: []
  };

  walk(value, (child, path) => {
    const n =
      typeof child === 'number'
        ? child
        : /^\d+$/.test(String(child))
          ? Number(child)
          : null;

    if (n == null) return;

    if (ids.pipelineIds.has(n)) {
      found.pipeline_ids.push({ id: n, path: pathText(path) });
    }

    if (ids.stageIds.has(n)) {
      found.stage_ids.push({ id: n, path: pathText(path) });
    }

    if (ids.customFieldIds.has(n)) {
      found.custom_field_ids.push({ id: n, path: pathText(path) });
    }
  });

  return {
    pipeline_ids: unique(found.pipeline_ids),
    stage_ids: unique(found.stage_ids),
    custom_field_ids: unique(found.custom_field_ids)
  };
}

function extractTriggers(bot) {
  const out = [];

  if (Array.isArray(bot.triggers)) out.push(...bot.triggers);
  if (Array.isArray(bot._embedded?.triggers)) out.push(...bot._embedded.triggers);

  walk(bot, (value, path) => {
    if (String(path[path.length - 1] ?? '').toLowerCase().includes('trigger')) {
      out.push({ path: pathText(path), raw: value });
    }
  });

  return unique(out);
}

function extractActions(bot) {
  const out = [];

  walk(bot, (value, path) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return;

    const last = String(path[path.length - 1] ?? '').toLowerCase();

    if (
      last.includes('action') ||
      value.handler === 'action' ||
      value.action != null ||
      value.action_type != null
    ) {
      out.push({
        id: value.id ?? value.uuid ?? null,
        type: value.params?.name ?? value.name ?? value.action ?? value.action_type ?? value.handler ?? null,
        path: pathText(path),
        raw: value
      });
    }
  });

  return unique(out);
}

function extractNodes(bot) {
  const out = [];
  const script = bot.script ?? bot.scenario ?? bot.schema ?? bot._embedded?.script ?? bot;

  walk(script, (value, path) => {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return;

    const p = pathText(path).toLowerCase();

    if (
      (p.includes('node') ||
        p.includes('block') ||
        p.includes('step') ||
        p.includes('question') ||
        p.includes('answer')) &&
      (value.id != null || value.uuid != null || value.type != null || value.handler != null)
    ) {
      out.push({
        id: value.id ?? value.uuid ?? null,
        type: value.type ?? value.handler ?? value.kind ?? null,
        name: value.name ?? value.title ?? value.params?.name ?? null,
        path: pathText(path),
        raw: value
      });
    }
  });

  return unique(out);
}

function extractFieldRefs(bot, customFieldIds) {
  const out = [];

  walk(bot, (value, path) => {
    const last = String(path[path.length - 1] ?? '').toLowerCase();

    const n =
      typeof value === 'number'
        ? value
        : /^\d+$/.test(String(value))
          ? Number(value)
          : null;

    if (n != null && customFieldIds.has(n)) {
      out.push({
        custom_field_id: n,
        path: pathText(path),
        evidence: 'value_matches_custom_field_id'
      });
    }

    if (last.includes('custom') || last.includes('field')) {
      out.push({
        path: pathText(path),
        key: path[path.length - 1],
        value,
        evidence: 'field_like_key'
      });
    }
  });

  return unique(out);
}

const rawPipelines = collectFromPack('pipelines', 'pipelines');
const rawCustomFields = collectFromPack('custom_fields', 'custom_fields');
const rawTags = collectFromPack('tags', 'tags');
const rawSalesbots = collectFromPack('salesbots', ['items', 'bots', 'salesbots']);
const rawLeadsSample = collectFromPack('leads_sample', 'leads');
const rawConversationSamples = readNodeItems(PACK_NODES.conversation_samples).flatMap(item => {
  if (item.pages != null) return asArrayPreserveObjects(item.pages);
  return [item];
}).map(unwrap);

const pipelines = rawPipelines.map(pipeline => {
  const statuses = arr(pipeline._embedded?.statuses ?? pipeline.statuses);

  return {
    id: pipeline.id,
    name: pipeline.name,
    sort: pipeline.sort ?? null,
    is_main: pipeline.is_main ?? null,
    is_unsorted_on: pipeline.is_unsorted_on ?? null,
    stages: statuses.map(stage => ({
      pipeline_id: pipeline.id,
      pipeline_name: pipeline.name,
      id: stage.id,
      name: stage.name,
      sort: stage.sort ?? null,
      color: stage.color ?? null,
      type: stage.type ?? null,
      raw: stage
    })),
    raw: pipeline
  };
});

const stages_flat = pipelines.flatMap(p => p.stages);

const custom_fields = rawCustomFields.map(field => ({
  id: field.id,
  name: field.name,
  type: field.type,
  code: field.code ?? null,
  sort: field.sort ?? null,
  is_api_only: field.is_api_only ?? null,
  enums: normalizeEnums(field.enums),
  required_statuses: arr(field.required_statuses),
  raw: field
}));

const tags = rawTags.map(tag => ({
  id: tag.id,
  name: tag.name,
  color: tag.color ?? null,
  raw: tag
}));

const ids = {
  pipelineIds: new Set(pipelines.map(p => p.id).filter(Boolean)),
  stageIds: new Set(stages_flat.map(s => s.id).filter(Boolean)),
  customFieldIds: new Set(custom_fields.map(f => f.id).filter(Boolean))
};

const salesbots = rawSalesbots.map(bot => {
  const refs = scanIds(bot, ids);

  return {
    id: bot.id,
    name: bot.name,
    type: bot.type ?? bot.type_functionality ?? null,
    is_active: bot.is_active ?? bot.active ?? null,
    created_at: bot.created_at ?? null,
    updated_at: bot.updated_at ?? null,
    triggers: extractTriggers(bot),
    actions: extractActions(bot),
    nodes: extractNodes(bot),
    custom_field_references: extractFieldRefs(bot, ids.customFieldIds),
    pipeline_references: refs.pipeline_ids,
    stage_references: refs.stage_ids,
    raw: bot
  };
});

const leads_sample = rawLeadsSample.map(lead => ({
  id: lead.id,
  name: lead.name,
  pipeline_id: lead.pipeline_id ?? null,
  status_id: lead.status_id ?? null,
  responsible_user_id: lead.responsible_user_id ?? null,
  price: lead.price ?? null,
  tags: arr(lead._embedded?.tags ?? lead.tags),
  contacts: arr(lead._embedded?.contacts ?? lead.contacts),
  companies: arr(lead._embedded?.companies ?? lead.companies),
  custom_fields_values: arr(lead.custom_fields_values),
  raw: lead
}));

function transcriptRoleLabel(role) {
  if (role === 'human') return 'CLIENTE';
  if (role === 'assistant' || role === 'ai') return 'AGENTE';
  return String(role || 'UNKNOWN').toUpperCase();
}

function normalizeTranscriptMessages(transcript) {
  return asArrayPreserveObjects(transcript)
    .map((message, index) => {
      const normalizedMessage = unwrap(message);
      return {
        turn: index + 1,
        role: normalizedMessage.role ?? 'unknown',
        speaker: transcriptRoleLabel(normalizedMessage.role),
        text: String(normalizedMessage.content ?? '').trim()
      };
    })
    .filter(message => message.text !== '');
}

const conversation_samples = rawConversationSamples.map(row => {
  const turns = normalizeTranscriptMessages(row.transcript);
  const transcript_text = turns
    .map(message => String(message.turn).padStart(2, '0') + '. ' + message.speaker + ': ' + message.text)
    .join('\n');

  return {
    sample_id: row.sample_id ?? null,
    session_hash: row.session_hash ?? null,
    purpose: 'golden_test_transcript_for_migration_parity',
    format: 'numbered_transcript_with_structured_turns',
    message_count: Number(row.message_count ?? turns.length),
    human_count: Number(row.human_count ?? turns.filter(message => message.role === 'human').length),
    assistant_count: Number(row.assistant_count ?? turns.filter(message => message.role === 'assistant' || message.role === 'ai').length),
    first_message_id: row.first_message_id ?? null,
    last_message_id: row.last_message_id ?? null,
    turns,
    transcript_text,
    analysis_hint: 'Usar turns para evaluacion estructurada y transcript_text para lectura humana. Roles: CLIENTE=usuario final, AGENTE=respuesta del bot/IA. Datos sensibles fueron anonimizados en SQL.',
    raw: row
  };
});

return [
  {
    json: {
      pipelines,
      stages_flat,
      custom_fields,
      tags,
      salesbots,
      leads_sample,
      conversation_samples,
      relationships: {
        pipeline_salesbot: salesbots.flatMap(bot =>
          bot.pipeline_references.map(ref => ({
            salesbot_id: bot.id,
            salesbot_name: bot.name,
            pipeline_id: ref.id,
            path: ref.path
          }))
        ),
        stage_salesbot: salesbots.flatMap(bot =>
          bot.stage_references.map(ref => ({
            salesbot_id: bot.id,
            salesbot_name: bot.name,
            stage_id: ref.id,
            path: ref.path
          }))
        ),
        custom_field_salesbot: salesbots.flatMap(bot =>
          bot.custom_field_references
            .filter(ref => ref.custom_field_id)
            .map(ref => ({
              salesbot_id: bot.id,
              salesbot_name: bot.name,
              custom_field_id: ref.custom_field_id,
              path: ref.path,
              evidence: ref.evidence
            }))
        ),
        implicit_automations: salesbots.flatMap(bot =>
          bot.triggers
            .filter(t => JSON.stringify(t).match(/status|stage|pipeline|lead_status|change/i))
            .map(trigger => ({
              salesbot_id: bot.id,
              salesbot_name: bot.name,
              likely_trigger: 'stage_or_pipeline_related',
              trigger
            }))
        )
      },
      _debug: {
        raw_counts: {
          pipelines: rawPipelines.length,
          custom_fields: rawCustomFields.length,
          tags: rawTags.length,
          salesbots: rawSalesbots.length,
          leads_sample: rawLeadsSample.length,
          conversation_samples: rawConversationSamples.length
        },
        first_page_shapes: Object.fromEntries(
          Object.entries(PACK_NODES).map(([section, nodeName]) => {
            const pages = readNodeItems(nodeName).flatMap(item => {
              if (item.pages != null) return arr(item.pages);
              return [item];
            });

            const first = unwrap(pages[0]);

            return [
              section,
              {
                pack_items: readNodeItems(nodeName).length,
                pages: pages.length,
                first_type: typeof first,
                first_keys: first && typeof first === 'object' ? Object.keys(first).slice(0, 30) : [],
                embedded_keys:
                  first?._embedded && typeof first._embedded === 'object'
                    ? Object.keys(first._embedded)
                    : []
              }
            ];
          })
        )
      },
      _metadata: {
        exported_at: new Date().toISOString(),
        source: 'Kommo API v4',
        counts: {
          pipelines: pipelines.length,
          stages: stages_flat.length,
          custom_fields: custom_fields.length,
          tags: tags.length,
          salesbots: salesbots.length,
          leads_sample: leads_sample.length,
          conversation_samples: conversation_samples.length
        }
      }
    }
  }
];

const SECTION = 'pipelines'; // cambiar: pipelines | custom_fields | tags | salesbots | leads_sample

return [
  {
    json: {
      section: SECTION,
      pages: $input.all().map(item => item.json)
    }
  }
];

